-- englishbygediel · dados de quem entra no Hub (rode DEPOIS do admin.sql e do hub.sql)
-- Cole tudo no Supabase: SQL Editor → New query → Run. Pode rodar de novo sem problema.
-- Cria:
--   hub_visitas      uma linha por visita: de onde veio, aparelho, idioma, fuso, campanha (utm), primeiro modo
--   hub_eventos      tudo o que a pessoa faz: cliques, cards vistos, fichas abertas, modo ligado, tempo e rolagem
--   leads_programa   quem preenche o chat de aplicação do Programa de Acompanhamento
--   leads_mentoria   quem pede a mentoria particular (o formulário externo pode gravar aqui)
-- O site só consegue GRAVAR; ler é só pro admin (painel).

create table if not exists public.hub_visitas (
  id          bigint generated always as identity primary key,
  created_at  timestamptz not null default now(),
  visitante   uuid not null,            -- o mesmo navegador volta com o mesmo código
  sessao      uuid not null,
  nova        boolean not null default true,  -- primeira vez desse visitante
  pagina      text check (char_length(pagina) <= 300),
  origem      text check (char_length(origem) <= 500),
  utm_source  text check (char_length(utm_source) <= 120),
  utm_medium  text check (char_length(utm_medium) <= 120),
  utm_campaign text check (char_length(utm_campaign) <= 160),
  utm_content text check (char_length(utm_content) <= 160),
  de          text check (char_length(de) <= 60),
  dispositivo text check (char_length(dispositivo) <= 400),
  tipo_aparelho text check (char_length(tipo_aparelho) <= 20),
  tela        text check (char_length(tela) <= 30),
  idioma      text check (char_length(idioma) <= 30),
  fuso        text check (char_length(fuso) <= 60)
);
create index if not exists hub_visitas_data_idx on public.hub_visitas (created_at);
create index if not exists hub_visitas_visitante_idx on public.hub_visitas (visitante);

create table if not exists public.hub_eventos (
  id          bigint generated always as identity primary key,
  created_at  timestamptz not null default now(),
  visitante   uuid not null,
  sessao      uuid not null,
  tipo        text not null check (tipo in ('clique','visto','ficha','modo','link','login','chat','tempo','secao')),
  item        text check (char_length(item) <= 120),
  rotulo      text check (char_length(rotulo) <= 200),
  secao       text check (char_length(secao) <= 60),
  modo        text check (char_length(modo) <= 40),
  valor       integer
);
create index if not exists hub_eventos_data_idx on public.hub_eventos (created_at);
create index if not exists hub_eventos_tipo_idx on public.hub_eventos (tipo, item);

create table if not exists public.leads_programa (
  id          bigint generated always as identity primary key,
  created_at  timestamptz not null default now(),
  visitante   uuid,
  sessao      uuid,
  modo        text check (char_length(modo) <= 40),
  nome        text check (char_length(nome) <= 160),
  whatsapp    text check (char_length(whatsapp) <= 40),
  instagram   text check (char_length(instagram) <= 80),
  modalidade  text check (char_length(modalidade) <= 40),
  parceiro_nome  text check (char_length(parceiro_nome) <= 160),
  parceiro_nivel text check (char_length(parceiro_nivel) <= 60),
  nivel       text check (char_length(nivel) <= 60),
  dificuldades text check (char_length(dificuldades) <= 400),
  objetivos   text check (char_length(objetivos) <= 400),
  tempo       text check (char_length(tempo) <= 60),
  porque      text check (char_length(porque) <= 2000),
  investimento text check (char_length(investimento) <= 80)
);

create table if not exists public.leads_mentoria (
  id          bigint generated always as identity primary key,
  created_at  timestamptz not null default now(),
  visitante   uuid,
  nome        text check (char_length(nome) <= 160),
  whatsapp    text check (char_length(whatsapp) <= 40),
  email       text check (char_length(email) <= 160),
  instagram   text check (char_length(instagram) <= 80),
  formato     text check (char_length(formato) <= 60),   -- individual, casal, amigos
  nivel       text check (char_length(nivel) <= 60),
  objetivo    text check (char_length(objetivo) <= 2000),
  respostas   jsonb                                      -- o formulário pode mandar tudo o mais aqui
);

do $$ declare t text; begin
  foreach t in array array['hub_visitas','hub_eventos','leads_programa','leads_mentoria'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists "site grava %s" on public.%I', t, t);
    execute format('create policy "site grava %s" on public.%I for insert to anon, authenticated with check (true)', t, t);
    execute format('drop policy if exists "admin le %s" on public.%I', t, t);
    execute format('create policy "admin le %s" on public.%I for select to authenticated using (public.is_admin())', t, t);
    execute format('drop policy if exists "admin apaga %s" on public.%I', t, t);
    execute format('create policy "admin apaga %s" on public.%I for delete to authenticated using (public.is_admin())', t, t);
  end loop;
end $$;

-- Atualização de 09/11: "Mentoria" virou "Programa de Acompanhamento" (checkout novo da Kiwify)
-- e "Mentoria" agora é a particular (formulário). Aplica no Hub que você já salvou pelo painel.
update public.site_config set updated_at = now(), dados = $hub$
